-- privileges and search_path
select cmp_ok((select count(*)::int from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname like 'h3\_%'), '>=', 7, 'public h3 functions exist');
select is((select count(*)::int from (select p.oid from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and (p.proname like '\_h3\_%' or p.proname like 'h3\_%')) f where has_function_privilege('anon', f.oid, 'execute')), 0, 'anon cannot execute any h3 function');
select is((select count(*)::int from (select p.oid from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and (p.proname like '\_h3\_%' or p.proname like 'h3\_%')) f where has_function_privilege('authenticated', f.oid, 'execute')), 0, 'authenticated cannot execute any h3 function');
select is((select count(*)::int from (select p.oid from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and (p.proname like '\_h3\_%' or p.proname like 'h3\_%')) f where not has_function_privilege('service_role', f.oid, 'execute')), 0, 'service_role can execute every h3 function');
select is((select count(*)::int from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and (p.proname like '\_h3\_%' or p.proname like 'h3\_%') and not (p.proconfig::text like '%search_path=public%')), 0, 'every h3 function pins search_path');
select is((select provolatile::text || proparallel::text || proisstrict::text from pg_proc where proname = 'h3_grid_disk'), 'istrue', 'h3_grid_disk is immutable, parallel safe, strict');

select * from finish();
rollback;
